const html = `<!doctype html><html lang="ko"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hello World — Jaeyong</title><style>body{margin:0;background:#080912;color:#f5f6ff;font:16px system-ui;padding:8vw;background-image:radial-gradient(circle at 80% 0,#29215b,#080912 55%)}main{max-width:900px;margin:auto}small{color:#9c7bff;letter-spacing:.16em}h1{font-size:clamp(42px,8vw,86px);line-height:.95;margin:16px 0 40px}h1 span{color:#9c7bff}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.card{background:#111321;border:1px solid #252a40;border-radius:16px;padding:22px}.card h2{font-size:12px;letter-spacing:.14em;color:#dfe3ff}.item{border-top:1px solid #252a40;padding:14px 0}.item:first-of-type{border:0}.muted{color:#9298b4}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><main><small>PERSONAL OPERATING SYSTEM</small><h1>Make it<br><span>meaningful.</span></h1><div class="grid"><section class="card"><h2>TODAY</h2><div class="item">빅데이터분석기사 학습 <span class="muted">60 min</span></div><div class="item">채용 일정 확인하기</div></section><section class="card"><h2>THIS WEEK</h2><div class="item">빅분기 1과목 복습</div><div class="item">지원 현황 정리</div><div class="item">프로젝트 등록</div></section><section class="card"><h2>SEPTEMBER FOCUS</h2><p>데이터로 문제를 읽고,<br><span style="color:#57d7f3">작은 결과물로 증명하기.</span></p></section><section class="card"><h2>QUICK NOTES</h2><p class="muted">아이디어와 다음에 읽을 것들을 쌓아두세요.</p></section></div></main></body></html>`;
const live = html.replace('</body>', '<script>const stamp=document.createElement("p");stamp.className="muted";stamp.style.marginTop="28px";document.querySelector("main").append(stamp);function tick(){stamp.textContent="LIVE · "+new Intl.DateTimeFormat("ko-KR",{hour:"2-digit",minute:"2-digit",second:"2-digit"}).format(new Date())+" · local preview"}tick();setInterval(tick,1000);document.querySelectorAll(".item").forEach((el,i)=>{if(i<2){el.style.cursor="pointer";el.addEventListener("click",()=>{el.style.opacity=el.style.opacity===".45"?"1":".45";el.style.textDecoration=el.style.textDecoration==="line-through"?"none":"line-through"})}})</script></body>');
export default { async fetch(){ return new Response(live,{headers:{"content-type":"text/html;charset=UTF-8"}}) } };
